import{c as t,Q as s,j as a,m as o}from"./chunks/framework.BPKcPtvA.js";const r="/images/system-status.png",d=JSON.parse('{"title":"System Status","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/system-status.md","filePath":"getting-started/system-status.md"}'),n={name:"getting-started/system-status.md"};function i(l,e,u,h,p,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="system-status" tabindex="-1">System Status <a class="header-anchor" href="#system-status" aria-label="Permalink to &quot;System Status&quot;">​</a></h1><p>Our most recent themes include a system status table directly in your WordPress Dashboard under <strong>Appearance &gt; About the Theme</strong>.</p><p>To access the system status table, you need to have plugin installation and activation capabilities enabled. More info about <a href="http://codex.wordpress.org/Roles_and_Capabilities" target="_blank" rel="noreferrer">WordPress roles and capabilities</a>.</p><p><img src="'+r+'" alt="System Status"></p><p>If you see red errors, you are likely not in compliance with the <a href="./../general/server-requirements.html">Server Requirements</a> for a modern WordPress installation. Most of our themes come packed with a page builder and a full options set that require decent server performance to run smoothly. Each red error includes a link to a tutorial showing how to fix the value.</p><p>You can always contact your host to have limits adjusted. Note that many hosts keep limits low to conserve resources — but you are paying for those resources and should expect your money&#39;s worth. These values are typically lower on <a href="./../general/low-budget-hosts.html">low budget hosts</a>.</p><p>The most important values to check:</p><ul><li><strong>WP Memory Limit</strong> — the maximum amount of RAM your site can use at one time. Reaching the limit causes a fatal error.</li><li><strong>Max Input Vars</strong> — the maximum number of variables your server can use. Low values can cause lost data in Theme Options, disappearing widgets, etc.</li></ul><h2 id="system-status-check-with-wordpress-phpinfo-plugin" tabindex="-1">System Status Check with WordPress phpinfo() Plugin <a class="header-anchor" href="#system-status-check-with-wordpress-phpinfo-plugin" aria-label="Permalink to &quot;System Status Check with WordPress phpinfo() Plugin&quot;">​</a></h2><p>If your theme does not include the system status table, you can use the <a href="https://wordpress.org/plugins/wordpress-php-info/" target="_blank" rel="noreferrer">WordPress phpinfo()</a> plugin instead.</p><p>Once installed, go to <strong>Settings &gt; phpinfo()</strong> in your admin panel.</p><p>The first column shows your installation value, the second shows your host&#39;s limit. The latter is often lower on cheaper hosting packages. Contact your host to have values adjusted if necessary.</p>',12)])])}const g=t(n,[["render",i]]);export{d as __pageData,g as default};
